CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS admins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE NOT NULL,description text NOT NULL DEFAULT '',price numeric(12,2) NOT NULL CHECK(price>=0),stock integer NOT NULL DEFAULT 0 CHECK(stock>=0),low_stock_threshold integer NOT NULL DEFAULT 5 CHECK(low_stock_threshold>=0),category_id uuid REFERENCES categories(id) ON DELETE SET NULL,images text[] NOT NULL DEFAULT '{}',featured boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_number text UNIQUE NOT NULL DEFAULT ('BH-'||upper(substr(encode(gen_random_bytes(6),'hex'),1,10))),customer_name text NOT NULL,email text NOT NULL,phone text NOT NULL,address text NOT NULL,city text NOT NULL,notes text NOT NULL DEFAULT '',subtotal numeric(12,2) NOT NULL,delivery_fee numeric(12,2) NOT NULL,total numeric(12,2) NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','processing','shipped','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id) ON DELETE SET NULL,product_name text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price numeric(12,2) NOT NULL,image_snapshot text);
CREATE INDEX IF NOT EXISTS products_active_idx ON products(active,featured DESC); CREATE INDEX IF NOT EXISTS orders_created_idx ON orders(created_at DESC); CREATE INDEX IF NOT EXISTS order_items_order_idx ON order_items(order_id);
-- Persistent session storage is created by connect-pg-simple on server startup.
